<?php
declare(strict_types=1);
$config=require __DIR__.'/../config/config.php';
function ppget(string $url,string $token):array{$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Accept: application/json','Content-Type: application/json','Authorization: Bearer '.$token],CURLOPT_TIMEOUT=>30,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode((string)$raw,true);if($code<200||$code>=300||!is_array($d))throw new RuntimeException('Unable to retrieve payment status.');return $d;}
function getStatus(string $tracking,array $config):array{$base=$config['pesapal']['environment']==='live'?'https://pay.pesapal.com/v3':'https://cybqa.pesapal.com/pesapalv3';$ch=curl_init($base.'/api/Auth/RequestToken');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode(['consumer_key'=>$config['pesapal']['consumer_key'],'consumer_secret'=>$config['pesapal']['consumer_secret']]),CURLOPT_HTTPHEADER=>['Accept: application/json','Content-Type: application/json'],CURLOPT_TIMEOUT=>30,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$a=json_decode((string)$raw,true);if($code<200||$code>=300||empty($a['token']))throw new RuntimeException('Payment authentication failed.');return ppget($base.'/api/Transactions/GetTransactionStatus?orderTrackingId='.rawurlencode($tracking),$a['token']);}
